Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include<bits/stdc++.h>
#define fi first
#define se second
#define LL long long
using namespace std;
const int M=1e9+7;
const int SZ=1<<20;
LL powmod(LL a,LL b){LL r=1;while(b){if(b&1)r=r*a%M;a=a*a%M;b>>=1;}return r;}
LL invmod(LL x){return powmod(x,M-2);}

int add(int a,int b){a+=b;return a>=M?a-M:a;}
int sub(int a,int b){a-=b;return a<0?a+M:a;}

void transform(int* a, int sign){
    for(int step=2; step<=SZ; step<<=1){
        int half=step>>1;
        for(int s=0; s<SZ; s+=step){
            for(int k=s; k<s+half; ++k){
                int x=a[k], y=a[k+half];
                a[k]= sign==1 ? add(x,y) : sub(x,y);
                // The next line is redundant but kept for clarity
                a[k+half]=a[k+half]; // no change
            }
        }
    }
}

int main(){
    int n;
    scanf("%d",&n);
    LL p[10][10];
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        scanf("%d",&p[i][j]);
        p[i][j]=p[i][j]*invmod(100)%M;
    }
    if(n<6) for(int i=n;i<6;i++) p[i][i]=1;
    n=6;
    int id[64], cnt=0;
    for(int i=0;i<64;i++) if(__builtin_popcount(i)==3) id[i]=cnt++;
    int A=63;
    int X[SZ]={0}, Y[SZ]={0};
    // helper lambda to compute product for given row masks
    auto calc_prob = [&](int r0,int r1,int r2, int base){
        LL pr=1;
        int masks[3]={r0,r1,r2};
        for(int r=0;r<3;r++){
            int msk=masks[r];
            for(int j=0;j<6;j++){
                if(msk>>j&1) pr=pr*p[base+r][j]%M;
                else pr=pr*(M+1-p[base+r][j])%M;
            }
        }
        return pr;
    };
    auto gen_mask = [&](int m1,int m2,int m3, bool complement){
        int mask=0;
        for(int a=0;a<6;a++) if(m1>>a&1)
            for(int b=0;b<6;b++) if(a!=b && (m2>>b&1))
                for(int c=0;c<6;c++) if(a!=c && b!=c && (m3>>c&1)){
                    int t=(1<<a)|(1<<b)|(1<<c);
                    if(complement) t^=A;
                    mask|=1<<id[t];
                }
        return mask;
    };
    for(int m1=0;m1<64;m1++) for(int m2=0;m2<64;m2++) for(int m3=0;m3<64;m3++){
        LL pr=calc_prob(m1,m2,m3,0);
        int mask=gen_mask(m1,m2,m3,false);
        X[mask]=add(X[mask],pr%M);
    }
    for(int m1=0;m1<64;m1++) for(int m2=0;m2<64;m2++) for(int m3=0;m3<64;m3++){
        LL pr=calc_prob(m1,m2,m3,3);
        int mask=gen_mask(m1,m2,m3,true);
        Y[mask]=add(Y[mask],pr%M);
    }
    transform(X,1); transform(Y,1);
    for(int i=0;i<SZ;i++) X[i]=(LL)X[i]*Y[i]%M;
    transform(X,-1);
    int ans=0;
    for(int i=1;i<SZ;i++) ans=add(ans,X[i]);
    printf("%d\n",ans);
    return 0;
}
